-- PROPOSTA EXPERIMENTAL; nao executar no produto. Core/bench usam schema1; reforco composto foi testado apenas em migracao.accdb.
CREATE TABLE Meta (ID INTEGER CONSTRAINT PK_Meta PRIMARY KEY,BaseID TEXT(40) NOT NULL,SchemaNo INTEGER,RevisionNo LONG);
CREATE TABLE WriterLease (ID INTEGER CONSTRAINT PK_Lease PRIMARY KEY,OwnerID TEXT(40),FenceNo LONG,StatusText TEXT(20));
CREATE TABLE Vehicles (VehicleID TEXT(40) CONSTRAINT PK_V PRIMARY KEY,Plate TEXT(20) NOT NULL);
CREATE TABLE Episodes (EpisodeID TEXT(40) CONSTRAINT PK_E PRIMARY KEY,VehicleID TEXT(40) NOT NULL,VersionNo LONG,StatusText TEXT(20),CurrentPID TEXT(40),PlaceCode TEXT(20),CONSTRAINT FK_EV FOREIGN KEY(VehicleID) REFERENCES Vehicles(VehicleID));
CREATE TABLE Operations (OperationID TEXT(40) CONSTRAINT PK_O PRIMARY KEY,EpisodeID TEXT(40) NOT NULL,ExpectedVersion LONG,KindText TEXT(20),AmountIn CURRENCY,AmountOut CURRENCY,CommandCanon LONGTEXT,SourceCanon LONGTEXT,PlannedPID TEXT(40),PlannedMID TEXT(40),StatusText TEXT(30),CONSTRAINT FK_OE FOREIGN KEY(EpisodeID) REFERENCES Episodes(EpisodeID));
CREATE TABLE Attempts (AttemptID TEXT(40) CONSTRAINT PK_A PRIMARY KEY,OperationID TEXT(40) NOT NULL,OwnerID TEXT(40),FenceNo LONG,CONSTRAINT FK_AO FOREIGN KEY(OperationID) REFERENCES Operations(OperationID));
CREATE TABLE Movements (MovementID TEXT(40) CONSTRAINT PK_M PRIMARY KEY,OperationID TEXT(40) NOT NULL,EpisodeID TEXT(40) NOT NULL,KindText TEXT(20),CONSTRAINT U_MO UNIQUE(OperationID),CONSTRAINT FK_MO FOREIGN KEY(OperationID) REFERENCES Operations(OperationID),CONSTRAINT FK_ME FOREIGN KEY(EpisodeID) REFERENCES Episodes(EpisodeID));
CREATE TABLE Projections (ProjectionID TEXT(40) CONSTRAINT PK_P PRIMARY KEY,EpisodeID TEXT(40) NOT NULL,MovementID TEXT(40) NOT NULL,AmountIn CURRENCY,AmountOut CURRENCY,CivilDate TEXT(10),DocNumber TEXT(20),AccessKey TEXT(44),PlaceCode TEXT(20),ContentCanon LONGTEXT,CONSTRAINT FK_PE FOREIGN KEY(EpisodeID) REFERENCES Episodes(EpisodeID),CONSTRAINT FK_PM FOREIGN KEY(MovementID) REFERENCES Movements(MovementID));
CREATE TABLE Receipts (ReceiptID TEXT(40) CONSTRAINT PK_R PRIMARY KEY,OperationID TEXT(40) NOT NULL,RevisionNo LONG,EffectCanon LONGTEXT,CONSTRAINT U_RO UNIQUE(OperationID),CONSTRAINT FK_RO FOREIGN KEY(OperationID) REFERENCES Operations(OperationID));
CREATE TABLE ChangeLog (AuditID COUNTER CONSTRAINT PK_L PRIMARY KEY,OperationID TEXT(40) NOT NULL,BeforeCanon LONGTEXT,AfterCanon LONGTEXT,CONSTRAINT FK_LO FOREIGN KEY(OperationID) REFERENCES Operations(OperationID));
CREATE TABLE Pending (EpisodeID TEXT(40) CONSTRAINT PK_Pending PRIMARY KEY,OperationID TEXT(40) NOT NULL,ReasonText TEXT(80),CONSTRAINT FK_NE FOREIGN KEY(EpisodeID) REFERENCES Episodes(EpisodeID),CONSTRAINT FK_NO FOREIGN KEY(OperationID) REFERENCES Operations(OperationID));
CREATE TABLE Provenance (LegacyRef TEXT(80) CONSTRAINT PK_Prov PRIMARY KEY,SourceHash TEXT(64),DecisionText TEXT(30),EpisodeID TEXT(40),EvidenceText LONGTEXT);
CREATE UNIQUE INDEX U_M_EP_ID ON Movements(EpisodeID,MovementID);
ALTER TABLE Projections ADD CONSTRAINT FK_PM_EP FOREIGN KEY(EpisodeID,MovementID) REFERENCES Movements(EpisodeID,MovementID);
-- Publicar SchemaNo=2 somente apos validacao de constraints e backup; operacao nao executada nos bancos de referencia.
